import{_ as o,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Cloud Storage Transitions and Beyond","description":"","frontmatter":{"title":"Ceph Cloud Storage Transitions and Beyond","date":"2026-06-26T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","RGW","对象存储","存储优化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Cloud_Storage_Transitions_and_Beyond.md","filePath":"posts/2026/Ceph_Cloud_Storage_Transitions_and_Beyond.md","lastUpdated":null}'),a={name:"posts/2026/Ceph_Cloud_Storage_Transitions_and_Beyond.md"};function r(n,e,s,c,d,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h2><h3 id="演讲者介绍" tabindex="-1">演讲者介绍 <a class="header-anchor" href="#演讲者介绍" aria-label="Permalink to &quot;演讲者介绍&quot;">​</a></h3><p>演讲者 John 感谢了他的导师 JC Lopez，四年前开始了 Ceph 学习之旅。John 在 YouTube 上维护一个名为&quot;Seph News at 10&quot;的视频博客频道。</p><h3 id="全球存储设备供应链危机" tabindex="-1">全球存储设备供应链危机 <a class="header-anchor" href="#全球存储设备供应链危机" aria-label="Permalink to &quot;全球存储设备供应链危机&quot;">​</a></h3><p>John 首先介绍了当前存储设备市场面临的严峻形势，引用了 Forbes 的数据：</p><ul><li><strong>SSD 固态存储</strong>：自去年四五月以来，年化通胀率高达 <strong>472%</strong>，涨幅最为剧烈</li><li><strong>HDD 机械硬盘</strong>：虽然年化通胀率较低，但在去年下半年出现了<strong>恶性通胀</strong>。由于企业从 SSD 转向 HDD，导致 HDD 也变得稀缺。据报道，Western Digital 的 24TB HDD 在 2026 年已经售罄</li><li><strong>磁带（Tape）</strong>：年化通胀率仅约 <strong>22%</strong>，表现最为平稳。但由于 HDD 紧缺导致更多采购转向磁带，近期也出现了一定涨幅。值得注意的是，石油也是磁带原材料之一</li></ul><p>Gartner 预测存储设备市场要到 <strong>2028 年 4 月</strong>才能恢复供需平衡，而且届时的价格仍将高于 2025 年水平，只是交付周期会缩短。Gartner 还指出，过去 45 年中类似的供应链危机已经发生过约 10-11 次，并非前所未见。</p><h3 id="ceph-rgw-存储分层与-cloud-transition" tabindex="-1">Ceph RGW 存储分层与 Cloud Transition <a class="header-anchor" href="#ceph-rgw-存储分层与-cloud-transition" aria-label="Permalink to &quot;Ceph RGW 存储分层与 Cloud Transition&quot;">​</a></h3><p>面对存储成本压力，Ceph 提供了<strong>无需激进措施</strong>的解决方案，主要针对 RADOS Gateway（RGW）对象存储：</p><p><strong>集群内分层（Tiering）：</strong></p><ul><li>支持多种存储类（Storage Classes）和保护策略</li><li>支持多种 Erasure Coding 编码方案：4+2、6+2（IBM 已验证，放大系数仅 1.33x）、8+3 等</li><li>相比传统的 Replica 3（3x 放大），EC 可降至 2x、1.5x 甚至更低</li><li>Bucket Index 建议使用 Replica 3，因为数据量小且性能更优</li><li>支持硬件加速压缩</li></ul><p><strong>集群外过渡（Cloud Transition）：</strong></p><ul><li>数据在集群内分层后，可进一步过渡到外部目标： <ul><li><strong>高密度本地 S3 对象存储</strong>（可能是另一个 Ceph 集群或其他厂商的 S3 存储）</li><li><strong>公有云</strong>：AWS、Google Cloud、IBM 等</li><li><strong>S3 磁带库</strong>：通过 S3 网关连接的磁带库（如 IBM Deep Archive，后端为 Diamondback 磁带库）</li></ul></li></ul><h3 id="非结构化数据的价值主张" tabindex="-1">非结构化数据的价值主张 <a class="header-anchor" href="#非结构化数据的价值主张" aria-label="Permalink to &quot;非结构化数据的价值主张&quot;">​</a></h3><p>John 强调了存储分层的必要性：</p><ul><li>非结构化数据是增长最快的存储领域，已持续 25 年</li><li>数据量越来越大，保存时间越来越长</li><li>研究表明，<strong>70%-85%</strong> 的非结构化数据在 180 天后不再被访问</li><li>甚至有客户报告 <strong>87%</strong> 的非结构化数据在 90 天后就无人触碰</li><li>然而这些冷数据仍存储在 Tier 1 存储上，并反复备份</li></ul><p>通过分层和过渡策略，可以将冷数据迁移到低成本存储层，延缓 Tier 1 存储扩容采购，从而应对当前的供应链危机。</p><h3 id="lifecycle-rule-工作流程" tabindex="-1">Lifecycle Rule 工作流程 <a class="header-anchor" href="#lifecycle-rule-工作流程" aria-label="Permalink to &quot;Lifecycle Rule 工作流程&quot;">​</a></h3><p><strong>管理员侧操作：</strong></p><ol><li>创建存储类（Storage Class），指定过渡类型（如 <code>cloud-s3</code> 用于公有云，<code>cloud-s3-glacier</code> 用于磁带）</li><li>配置过渡目标的 Endpoint、Access Key、Secret Key、目标 Bucket 名称</li><li>可选配置：是否保留对象头（Retain Head Object）、Restore 保留天数、多部分上传大小等</li><li>重启 RGW 服务使配置生效</li></ol><p><strong>用户侧操作：</strong></p><ol><li>正常上传对象到 Bucket</li><li>在 Bucket 上应用 Lifecycle Rule（如：前缀为 <code>img</code> 且超过 3 天的对象过渡到 AWS）</li><li>管理员可通过 <code>radosgw-admin lc process</code> 强制立即处理 Lifecycle 规则</li></ol><p><strong>数据召回（Recall）：</strong></p><ul><li>过渡后的对象在源 Bucket 中显示为 <strong>零字节头（Zero-byte Head Stub）</strong></li><li>用户执行 GET 或 Restore Object 操作时，Ceph 会自动从过渡目标拉回数据（Transparent Recall）</li><li>召回的数据在本地保留指定天数后再次清除</li><li>使用 <code>GET bucket-lifecycle</code> 验证规则，使用 <code>HEAD object</code> 查看对象状态和大小</li></ul><h3 id="现场演示" tabindex="-1">现场演示 <a class="header-anchor" href="#现场演示" aria-label="Permalink to &quot;现场演示&quot;">​</a></h3><p>John 进行了两项演示：</p><p><strong>演示一：Cloud Transition to AWS</strong></p><ol><li>在 Ceph Dashboard 的 Object Gateways 中验证集群状态</li><li>查看已配置的存储类：<code>glacier</code>（指向磁带）和 <code>AWS</code>（指向 AWS S3）</li><li>创建新 Bucket <code>seph-days-to-aws</code></li><li>使用 <code>rclone sync</code> 上传约 24 个文件（包括大型 JPEG 图片）</li><li>应用 Lifecycle Rule：前缀 <code>img</code> 且超过 3 天的对象过渡到 AWS</li><li>强制执行 Lifecycle 处理后，源 Bucket 中的图片变为零字节</li><li>在 AWS 端的 <code>jr-seph-archive</code> Bucket 中确认数据已迁移（以源 Bucket 名称作为对象前缀）</li><li>执行 Quick Look / GET 操作，数据透明召回，对象大小恢复</li></ol><p><strong>演示二：Cloud Transition to Tape</strong></p><ol><li>配置 <code>glacier</code> 存储类，Tier Type 为 <code>cloud-s3-glacier</code>，指向 S3 磁带库</li><li>创建 Bucket <code>seph-days-to-tape</code></li><li>上传图片后强制执行 Lifecycle 处理</li><li>确认数据已过渡到磁带库</li></ol><h3 id="关键技术细节" tabindex="-1">关键技术细节 <a class="header-anchor" href="#关键技术细节" aria-label="Permalink to &quot;关键技术细节&quot;">​</a></h3><p><strong>开发调试参数：</strong></p><ul><li><code>ceph config set client.radosgw rgwlc_debug_interval 60</code>：将 60 秒映射为 1 天，加速测试 Lifecycle 规则</li><li>使用自签名证书时可配置 RGW 跳过 SSL 验证</li></ul><p><strong>Lifecycle Rule 语法要点：</strong></p><ul><li><code>Prefix</code>：匹配对象前缀</li><li><code>Transition</code>：指定目标 Storage Class 和天数</li><li><code>NoncurrentVersionExpiration</code>：处理 S3 版本控制下的非当前版本</li><li>支持按对象大小过滤（如仅过渡大于 5MB 的对象）</li></ul><p><strong>每次变更 Storage Class 或相关配置后，必须重启 RGW 服务。</strong></p><h3 id="管理员与用户职责分离" tabindex="-1">管理员与用户职责分离 <a class="header-anchor" href="#管理员与用户职责分离" aria-label="Permalink to &quot;管理员与用户职责分离&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td><strong>Ceph 管理员</strong></td><td>创建/配置存储类、查看 Lifecycle 规则、强制触发处理、查看集群状态</td></tr><tr><td><strong>终端用户</strong></td><td>上传对象、应用 Lifecycle Rule、执行 GET/Restore 召回数据</td></tr></tbody></table><h3 id="核心价值总结" tabindex="-1">核心价值总结 <a class="header-anchor" href="#核心价值总结" aria-label="Permalink to &quot;核心价值总结&quot;">​</a></h3><p>Ceph RADOS Gateway 的 Cloud Transition 功能实现了一个<strong>无边界对象存储</strong>：</p><ul><li>集群内通过 EC 和压缩实现高效分层</li><li>集群外可过渡到公有云、本地高密度 S3 或 S3 磁带库</li><li>透明召回机制对用户几乎无感</li><li>在存储设备供应链紧张的背景下，有效延缓存储扩容采购</li><li>磁带存储具有低碳足迹、高密度和一定程度的&quot;伪气隙&quot;（Air Gap）安全特性</li></ul>',41)])])}const g=o(a,[["render",r]]);export{p as __pageData,g as default};
